/* The PWA's JS core must give exactly the Windows app's (Python) results.
 * Fixtures: tests/fixtures/core/parity.json, generated by tools/gen_core_fixtures.py
 * from ads_core itself; tests/test_core_fixtures.py fails if they go stale. */
import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {resolveDateRange,reportOutput,googleDailyRows,metaDailyRows} from '../static/core/reports.js';
import {googleCampaigns,metaCampaigns} from '../static/core/campaigns.js';
import {evaluateCampaigns,computeBaselines,verifyOutcome} from '../static/core/playbook.js';

const {cases}=JSON.parse(readFileSync(new URL('./fixtures/core/parity.json',import.meta.url),'utf8'));
const errorOf=fn=>{try{return fn();}catch(e){return {error:e.message};}};
const RUN={
 date_range:i=>errorOf(()=>resolveDateRange(i.period,i.from,i.to,i.today)),
 report_output:i=>reportOutput(i.rows,i.currency,i.source),
 google_report:i=>reportOutput(googleDailyRows(i.pages),i.currency,'google_live'),
 meta_report:i=>reportOutput(metaDailyRows(i.body),i.currency,'meta_live'),
 google_campaigns:i=>errorOf(()=>googleCampaigns(i.pages)),
 meta_campaigns:i=>errorOf(()=>metaCampaigns(i)),
 baselines:i=>computeBaselines(i.snapshots),
 verify:i=>verifyOutcome(i.base,i.cur,i.code),
 playbook:i=>evaluateCampaigns(i.campaigns,i.platform,i.currency,i.goal,i.baselines),
};

for(const kind of Object.keys(RUN)){
 test('parity with the Windows app: '+kind,()=>{
   const mine=cases.filter(c=>c.kind===kind);
   assert.ok(mine.length>0,'no fixtures for '+kind);
   mine.forEach((c,n)=>{
     // JSON round trip: the fixtures went through JSON too (undefined drops, -0 -> 0).
     const actual=JSON.parse(JSON.stringify(RUN[kind](structuredClone(c.input))));
     assert.deepStrictEqual(actual,c.expected,kind+' case #'+n+' input='+JSON.stringify(c.input).slice(0,400));
   });
 });
}
